using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;

public static class P29MapTests {
 static void Check(bool ok,string why){if(!ok)throw new InvalidOperationException("P29_TEST: "+why);}
 public static void PreviewChecks(){
  LaneArrowAppearanceTests.Run();var p=ProjectMapStore.Load(ProjectMapBuild.Root);Validate(p,P29MapEdit.Preview(p));
 }
 public static void Validate(ProjectMapPackage p,RoadMapDocument d){
  string before=JsonUtility.ToJson(p);var expected=P29MapEdit.Preview(p);var normalized=d.Copy();normalized.revision=expected.revision;normalized.savedAt=expected.savedAt;normalized.projectRevision=expected.projectRevision;Check(before==JsonUtility.ToJson(p),"baseline/input changed");Check(normalized.ToJson()==expected.ToJson(),"candidate differs from deterministic preview");
  var roots=new[]{P29MapEdit.EInner,P29MapEdit.EOuter,P29MapEdit.WInner,P29MapEdit.WOuter};var family=p.document.lanes.Single(l=>l.id==P29MapEdit.EInner).sourceId;var allowed=new HashSet<string>(p.document.lanes.Where(l=>l.sourceId==family||l.next.Contains(P29MapEdit.WInner)||l.next.Contains(P29MapEdit.WOuter)).Select(l=>l.id));
  for(int i=0;i<p.document.lanes.Length;i++){var a=p.document.lanes[i];var b=d.lanes[i];Check(a.id==b.id&&a.sourceId==b.sourceId&&a.sourceOffset==b.sourceOffset,"old ID/order/sourceOffset "+a.id);if(!allowed.Contains(a.id))Check(JsonUtility.ToJson(a)==JsonUtility.ToJson(b),"unrelated lane changed "+a.id);}
  for(int i=0;i<p.document.scene.objects.Length;i++){var a=p.document.scene.objects[i];var b=d.scene.objects[i];bool scopedRoad=a.kind=="road"&&(P29MapEdit.Sources.Any(id=>a.id=="road:"+id)||a.id.StartsWith("road:polish:")&&allowed.Contains(a.id.Substring("road:polish:".Length)));if(!scopedRoad)Check(JsonUtility.ToJson(a)==JsonUtility.ToJson(b),"unrelated road/sidewalk/object changed "+a.id);}
  Check(d.facilities.Length==p.document.facilities.Length+1,"one observed paint metadata entry only");for(int i=0;i<p.document.facilities.Length;i++)Check(JsonUtility.ToJson(d.facilities[i])==JsonUtility.ToJson(p.document.facilities[i]),"existing facility changed");
  var errors=RoadMapValidator.Validate(p.baseline,d).Where(e=>e.error).ToArray();Check(errors.Length==0,string.Join(" / ",errors.Take(10).Select(e=>e.ToString())));var map=RoadMapComposer.Compose(p.baseline,d);EungyeConnectivityRepair.Apply(map,p.baseline);var graph=new HdRoadGraph(map);
  var refPath=new AssistedRoadNetwork.Path(p.document.lanes.Single(l=>l.id==P29MapEdit.EInner).points.Select(q=>q.V()).ToArray());
  foreach(float fraction in new[]{.1f,.5f,.9f}){var point=refPath.Position(refPath.length*fraction);var heading=refPath.Tangent(refPath.length*fraction);var crossing=graph.edges.Where(e=>!e.disabled&&e.sourceId==family&&e.turn==0&&e.change==0&&!e.id.StartsWith("join:")&&Crosses(e.points,point,heading)).ToArray();Check(crossing.Length==3&&crossing.Count(e=>Vector3.Dot(e.points.Last().V()-e.points[0].V(),heading)>0)==2,"E2/W1 crosssection "+fraction);}
  Check(graph.edges.Single(e=>e.id==P29MapEdit.WOuter).disabled&&!graph.edges.Any(e=>!e.disabled&&e.next.Contains(Array.FindIndex(graph.edges,l=>l.id==P29MapEdit.WOuter))),"disabled west lane has no active incoming edges");
  var inner=d.lanes.Single(l=>l.id==P29MapEdit.Terminal(P29MapEdit.EInner));var outer=d.lanes.Single(l=>l.id==P29MapEdit.Terminal(P29MapEdit.EOuter));Check(inner.next.Length==1&&d.lanes.Single(l=>l.id==inner.next[0]).turn==-1,"east inner left-only");Check(outer.next.Select(id=>d.lanes.Single(l=>l.id==id).turn).Distinct().OrderBy(x=>x).SequenceEqual(new[]{0,1}),"outer actual S+R permissions retained");Check(outer.next.Contains("join:reviewed:J7917:entry:14"),"reviewed J7917 right target retained");
  var arrows=LaneDirectionPaint.Layout(map);foreach(var pair in new[]{new[]{inner.id,"1"},new[]{outer.id,"2"}}){int index=Array.FindIndex(graph.edges,e=>e.id==pair[0]);Check(arrows.Any(a=>a.edgeIndex==index&&a.turns==int.Parse(pair[1])),"observed world/minimap arrow "+pair[0]);Check(!arrows.Any(a=>a.edgeIndex==index&&a.turns!=int.Parse(pair[1])),"conflicting inferred arrow "+pair[0]);}
  int strokes=0;LaneDirectionPaint.Paint(map,(name,q,dir,width,length,yellow)=>{if(name!="Lane arrow "+outer.id)return;strokes++;foreach(float at in new[]{-length*.5f,0,length*.5f})Check(OnRoad(map,q+dir*at,width*.5f),"outer observed arrow on pavement");});Check(strokes==4,"outer is actual straight-only glyph");
  var changed=d.lanes.Where(l=>!l.disabled&&!p.document.lanes.Any(a=>a.id==l.id&&JsonUtility.ToJson(a)==JsonUtility.ToJson(l))).ToArray();foreach(var lane in changed){var edge=graph.edges.Single(e=>e.id==lane.id);Footprint(map,edge);foreach(int next in edge.next)Check(Vector3.Distance(edge.points.Last().V(),graph.edges[next].points[0].V())<.03f,"changed connector/segment seam "+edge.id);}
  foreach(string root in new[]{P29MapEdit.EInner,P29MapEdit.EOuter}){string other=root==P29MapEdit.EInner?P29MapEdit.EOuter:P29MapEdit.EInner;int from=Array.FindIndex(graph.edges,e=>e.id==root),to=Array.FindIndex(graph.edges,e=>e.id==P29MapEdit.Terminal(other));var route=graph.Route(from,2,to,2);Check(route!=null&&route.path.length<45&&route.edges.Any(i=>graph.edges[i].change!=0),"adjacent east lane preparation "+root);}
  var originalMap=p.Compose();EungyeConnectivityRepair.Apply(originalMap,p.baseline);var originalCatalog=PassengerStopCatalog.For(originalMap);var catalog=PassengerStopCatalog.For(map);Check(catalog.Stops.Length==39&&catalog.Entries.Select(e=>e.StopId).SequenceEqual(originalCatalog.Entries.Select(e=>e.StopId)),"39 ordered stop IDs retained");int pairs=0;foreach(var a in catalog.Stops)foreach(var b in catalog.Stops)if(a!=b){Check(graph.Route(a.laneEdge,a.laneAt,b.laneEdge,b.laneAt)!=null,"stop route lost "+a.name+" -> "+b.name);pairs++;}Check(pairs==1482,"all directed stop pairs");Debug.Log("P29_PREVIEW_OK E2/W1 innerL outerPaintS outerNavigationS+R stops39 pairs1482 baseline-and-sidewalks-preserved no-save");
 }
 static bool Crosses(MapPoint[] pts,Vector3 point,Vector3 forward){for(int i=1;i<pts.Length;i++){float a=Vector3.Dot(pts[i-1].V()-point,forward),b=Vector3.Dot(pts[i].V()-point,forward);if(a<=0&&b>0||b<=0&&a>0)return true;}return false;}
 static bool OnRoad(MapData map,Vector3 p,float margin){return map.roads.Any(r=>{float error;new AssistedRoadNetwork.Path(r.points.Select(q=>q.V()).ToArray()).Project(p,out error);return error+margin<=r.width*.5f;});}
 static void Footprint(MapData map,HdEdge edge){string reason;if(EungyeConnectivityRepair.FootprintClear(map,edge,out reason))return;Check(reason=="reverse/abrupt heading","footprint "+edge.id+": "+reason);var path=new AssistedRoadNetwork.Path(edge.points.Select(q=>q.V()).ToArray());for(float start=0;start<path.length;start+=1){float end=Mathf.Min(path.length,start+2);var pts=new List<MapPoint>();for(float at=start;at<end-.001f;at+=.5f){var q=path.Position(at);pts.Add(new MapPoint{x=q.x,z=q.z});}var last=path.Position(end);pts.Add(new MapPoint{x=last.x,z=last.z});Check(EungyeConnectivityRepair.FootprintClear(map,new HdEdge{points=pts.ToArray()},out reason),"local swept footprint "+edge.id+" station="+start+": "+reason);}}
}
